index 0000000..d041f73
--- /dev/null
+++ b/apps/web/src/features/learning/studio/data/autosave.ts
@@ -0,0 +1,131 @@
+import { isStudioError } from './client';
+
+/** Where the draft stands, shown next to the course title. */
+export type SaveStatus = 'saved' | 'unsaved' | 'saving' | 'offline' | 'conflict' | 'error';
+
+/** Timers, injectable for tests. */
+export type AutosaveTimers = {
+  set(run: () => void, ms: number): unknown;
+  clear(handle: unknown): void;
+};
+
+/** Options for {@link createAutosave}. */
+export type AutosaveOptions<T> = {
+  /** Saves the whole draft against `revision` and returns the new revision. */
+  save(value: T, revision: number): Promise<{ revision: number }>;
+  /** The revision the draft was loaded at. */
+  revision: number;
+  onStatus?(status: SaveStatus): void;
+  /** Quiet time after the last change before saving. Default 800 ms. */
+  delayMs?: number;
+  /** Wait before trying again after a failed save. Default 5 s. */
+  retryMs?: number;
+  timers?: AutosaveTimers;
+};
+
+/**
+ * Saves the latest draft after a quiet moment, one save at a time. When offline or after an error it keeps
+ * the change and tries again; after a conflict (someone saved a newer revision) it waits for `resume`.
+ */
+export type Autosave<T> = {
+  readonly status: SaveStatus;
+  readonly revision: number;
+  /** Queues `value`, the whole draft, to be saved. */
+  change(value: T): void;
+  /** Saves any queued change now and waits for it. Resolves to the status afterwards. */
+  flush(): Promise<SaveStatus>;
+  /** After a conflict: carry on from `revision` (e.g. to keep this version over theirs). */
+  resume(revision: number): void;
+  /** Stops saving. Queued changes are dropped. */
+  dispose(): void;
+};
+
+const browserTimers: AutosaveTimers = {
+  set: (run, ms) => setTimeout(run, ms),
+  clear: (handle) => clearTimeout(handle as ReturnType<typeof setTimeout>),
+};
+
+/** Starts autosaving a draft loaded at `options.revision`. */
+export function createAutosave<T>(options: AutosaveOptions<T>): Autosave<T> {
+  const { delayMs = 800, retryMs = 5000, timers = browserTimers } = options;
+  let status: SaveStatus = 'saved';
+  let revision = options.revision;
+  let pending: { value: T } | null = null;
+  let timer: unknown = null;
+  let running: Promise<void> | null = null;
+  let disposed = false;
+
+  const setStatus = (next: SaveStatus) => {
+    if (next === status) return;
+    status = next;
+    options.onStatus?.(next);
+  };
+  const stopTimer = () => {
+    if (timer !== null) timers.clear(timer);
+    timer = null;
+  };
+  const schedule = (ms: number) => {
+    stopTimer();
+    timer = timers.set(() => {
+      timer = null;
+      void run();
+    }, ms);
+  };
+
+  async function attempt(value: T): Promise<void> {
+    setStatus('saving');
+    try {
+      revision = (await options.save(value, revision)).revision;
+      setStatus(pending ? 'unsaved' : 'saved');
+    } catch (error) {
+      pending ??= { value };
+      if (isStudioError(error, 'conflict')) setStatus('conflict');
+      else setStatus(isStudioError(error, 'offline') ? 'offline' : 'error');
+    }
+    if (disposed || !pending || status === 'conflict' || timer !== null) return;
+    schedule(status === 'unsaved' ? delayMs : retryMs);
+  }
+
+  function run(): Promise<void> {
+    if (running) return running;
+    if (disposed || !pending || status === 'conflict') return Promise.resolve();
+    const { value } = pending;
+    pending = null;
+    running = attempt(value).finally(() => {
+      running = null;
+    });
+    return running;
+  }
+
+  return {
+    get status() {
+      return status;
+    },
+    get revision() {
+      return revision;
+    },
+    change(value) {
+      if (disposed) return;
+      pending = { value };
+      if (status === 'saved') setStatus('unsaved');
+      if (status !== 'conflict') schedule(delayMs);
+    },
+    async flush() {
+      while (running) await running;
+      stopTimer();
+      await run();
+      return status;
+    },
+    resume(next) {
+      if (disposed || status !== 'conflict') return;
+      revision = next;
+      setStatus(pending ? 'unsaved' : 'saved');
+      void run();
+    },
+    dispose() {
+      disposed = true;
+      pending = null;
+      stopTimer();
+    },
+  };
+}
diff --git a/apps/web/src/features/learning/studio/data/client.ts b/apps/web/src/features/learning/studio/data/client.ts
new file mode 100644
index 0000000..f414682
--- /dev/null
+++ b/apps/web/src/features/learning/studio/data/client.ts
@@ -0,0 +1,98 @@
+import type {
+  Block,
+  Course,
+  CourseType,
+  Id,
+  PublishNotify,
+  PublishProblem,
+} from '@carehub/learning';
+
+// The Studio talks to drafts through this interface (api.md, "Studio course API"). The local implementation
+// keeps drafts in the browser until the server version lands; both behave the same way, including the
+// revision check on save and the publish problems.
+
+/** Where a course stands: never published, published as it is, or published with unpublished changes. */
+export type StudioCourseState = 'draft' | 'live' | 'changed';
+
+/** One course in the Studio list. */
+export type StudioCourseSummary = {
+  id: Id;
+  title: string;
+  type: CourseType;
+  state: StudioCourseState;
+  /** The live version number, or null before the first publish. */
+  version: number | null;
+  /** ISO date-time of the last saved change. */
+  updatedAt: string;
+  archived: boolean;
+  listed: boolean;
+};
+
+/** A draft with the revision to send back when saving it. */
+export type StudioDraft = { course: Course; revision: number; liveVersion: number | null };
+
+/** A published version, newest first in lists. */
+export type StudioCourseVersion = {
+  version: number;
+  publishedAt: string;
+  title: string;
+  note?: string;
+};
+
+/** An example course to start from. */
+export type StudioExample = { id: Id; title: string; type: CourseType; summary: string };
+
+/** Saved blocks to insert again. */
+export type BlockTemplate = { id: Id; name: string; blocks: Block[] };
+
+/**
+ * Why a Studio call failed, following the API's error codes (api/errors.ts): `invalid` (400), `forbidden` (403),
+ * `not_found` (404), `conflict` (409, someone saved a newer revision), `cannot_publish` (422, with the problems),
+ * `offline` (no answer from the server) and `failed` (anything else).
+ */
+export type StudioErrorCode =
+  'invalid' | 'forbidden' | 'not_found' | 'conflict' | 'cannot_publish' | 'offline' | 'failed';
+
+/** A failed Studio call. `problems` lists what to fix when publishing was refused. */
+export class StudioError extends Error {
+  readonly code: StudioErrorCode;
+  readonly problems: PublishProblem[];
+
+  constructor(code: StudioErrorCode, message: string, problems: PublishProblem[] = []) {
+    super(message);
+    this.name = 'StudioError';
+    this.code = code;
+    this.problems = problems;
+  }
+}
+
+/** True when `error` is a StudioError with `code`. */
+export function isStudioError(error: unknown, code?: StudioErrorCode): error is StudioError {
+  return error instanceof StudioError && (code === undefined || error.code === code);
+}
+
+/** Everything the Studio screens need from storage. Every call is async, like the server. */
+export interface StudioClient {
+  listCourses(options?: { archived?: boolean }): Promise<StudioCourseSummary[]>;
+  /** A new draft of `type`, or a copy of an example course. */
+  createCourse(input: { type: CourseType; title?: string; exampleId?: Id }): Promise<StudioDraft>;
+  getCourse(courseId: Id): Promise<StudioDraft>;
+  /** Saves the draft. Fails with `conflict` when someone saved a newer revision first. */
+  saveCourse(courseId: Id, course: Course, revision: number): Promise<{ revision: number }>;
+  /** Publishes the saved draft as a new version. Fails with `cannot_publish` when it isn't ready. */
+  /** `notify`: what happens to people who already started (0311): nobody moves, move and tell, or retake. */
+  publish(
+    courseId: Id,
+    input: { notify: PublishNotify; note?: string },
+  ): Promise<{ version: number }>;
+  listVersions(courseId: Id): Promise<StudioCourseVersion[]>;
+  /** Publishes a copy of an earlier version (the draft becomes that version too). */
+  rollback(courseId: Id, version: number): Promise<{ version: number }>;
+  duplicate(courseId: Id): Promise<StudioCourseSummary>;
+  archive(courseId: Id): Promise<StudioCourseSummary>;
+  unarchive(courseId: Id): Promise<StudioCourseSummary>;
+  listExamples(): Promise<StudioExample[]>;
+  listBlockTemplates(): Promise<BlockTemplate[]>;
+  saveBlockTemplate(input: { name: string; blocks: Block[] }): Promise<BlockTemplate>;
+  deleteBlockTemplate(templateId: Id): Promise<void>;
+}
