@@ -0,0 +1,143 @@
+import { describe, expect, it } from 'vitest';
+import { checkPublishable, sampleCourses } from '@carehub/learning';
+import type { Block } from '@carehub/learning';
+import { isStudioError } from './client';
+import { createMemoryStudioClient } from './memory-client';
+import type { MemoryStudioOptions } from './memory-client';
+
+// Fictional data only.
+function setup(extra: MemoryStudioOptions = {}) {
+  let n = 0;
+  let t = Date.parse('2026-10-27T09:00:00.000Z');
+  return createMemoryStudioClient({
+    newId: () => `id-${++n}`,
+    now: () => new Date((t += 1000)),
+    ...extra,
+  });
+}
+
+const example = sampleCourses.find((c) => checkPublishable(c).length === 0);
+const failsWith = async (promise: Promise<unknown>, code: string) => {
+  const error = await promise.then(
+    () => null,
+    (e: unknown) => e,
+  );
+  expect(isStudioError(error) ? error.code : error).toBe(code);
+  return error;
+};
+
+describe('memory Studio client', () => {
+  it('creates drafts from a type or an example', async () => {
+    const client = setup();
+    const blank = await client.createCourse({ type: 'standard', title: '  ' });
+    expect(blank.course).toMatchObject({ id: 'id-1', title: 'Untitled course', type: 'standard' });
+    expect(blank).toMatchObject({ revision: 1, liveVersion: null });
+
+    expect(example).toBeDefined();
+    if (!example) return;
+    const copy = await client.createCourse({ type: 'standard', exampleId: example.id });
+    expect(copy.course.title).toBe(example.title);
+    expect(copy.course.id).not.toBe(example.id);
+    await failsWith(client.createCourse({ type: 'standard', exampleId: 'gone' }), 'not_found');
+
+    const list = await client.listCourses();
+    expect(list.map((c) => [c.id, c.state, c.version])).toEqual([
+      [copy.course.id, 'draft', null],
+      ['id-1', 'draft', null],
+    ]);
+    expect((await client.listExamples()).length).toBe(sampleCourses.length);
+  });
+
+  it('checks the revision and the format on save', async () => {
+    const client = setup();
+    const { course, revision } = await client.createCourse({ type: 'standard', title: 'Refunds' });
+    expect(
+      await client.saveCourse(course.id, { ...course, title: 'Refunds 101' }, revision),
+    ).toEqual({
+      revision: 2,
+    });
+    await failsWith(client.saveCourse(course.id, course, revision), 'conflict');
+    await failsWith(client.saveCourse(course.id, { ...course, title: '' }, 2), 'invalid');
+    await failsWith(client.saveCourse('nope', course, 2), 'not_found');
+    expect((await client.getCourse(course.id)).course.title).toBe('Refunds 101');
+  });
+
+  it('publishes, tracks changes, lists versions and rolls back', async () => {
+    if (!example) return;
+    const client = setup();
+    const empty = await client.createCourse({ type: 'standard', title: 'Empty' });
+    const refused = await failsWith(
+      client.publish(empty.course.id, { notify: 'none' }),
+      'cannot_publish',
+    );
+    expect(isStudioError(refused) && refused.problems.length).toBeGreaterThan(0);
+
+    const { course, revision } = await client.createCourse({
+      type: 'standard',
+      exampleId: example.id,
+    });
+    expect(await client.publish(course.id, { notify: 'none', note: ' First ' })).toEqual({
+      version: 1,
+    });
+    const state = async () => (await client.listCourses()).find((c) => c.id === course.id)?.state;
+    expect(await state()).toBe('live');
+    await client.saveCourse(course.id, { ...course, title: 'Greeting callers, again' }, revision);
+    expect(await state()).toBe('changed');
+    expect(await client.publish(course.id, { notify: 'tell' })).toEqual({ version: 2 });
+
+    expect(await client.rollback(course.id, 1)).toEqual({ version: 3 });
+    const versions = await client.listVersions(course.id);
+    expect(versions.map((v) => [v.version, v.title, v.note])).toEqual([
+      [3, course.title, 'Rolled back to version 1'],
+      [2, 'Greeting callers, again', undefined],
+      [1, course.title, 'First'],
+    ]);
+    const draft = await client.getCourse(course.id);
+    expect(draft).toMatchObject({ revision: 3, liveVersion: 3, course: { title: course.title } });
+    expect(await state()).toBe('live');
+    await failsWith(client.rollback(course.id, 9), 'not_found');
+  });
+
+  it('duplicates as an unpublished copy and archives', async () => {
+    if (!example) return;
+    const client = setup();
+    const { course } = await client.createCourse({ type: 'standard', exampleId: example.id });
+    await client.publish(course.id, { notify: 'none' });
+    const copy = await client.duplicate(course.id);
+    expect(copy).toMatchObject({ title: `Copy of ${course.title}`, state: 'draft', version: null });
+
+    expect(await client.archive(course.id)).toMatchObject({ archived: true });
+    expect((await client.listCourses()).map((c) => c.id)).toEqual([copy.id]);
+    expect((await client.listCourses({ archived: true })).map((c) => c.id)).toEqual([course.id]);
+    await client.unarchive(course.id);
+    expect((await client.listCourses()).length).toBe(2);
+  });
+
+  it('saves and deletes block templates', async () => {
+    const client = setup();
+    const blocks: Block[] = [{ id: 'b1', type: 'divider', style: 'line' }];
+    const saved = await client.saveBlockTemplate({ name: ' Sign-off ', blocks });
+    expect(saved).toEqual({ id: 'id-1', name: 'Sign-off', blocks });
+    await failsWith(client.saveBlockTemplate({ name: ' ', blocks }), 'invalid');
+    await failsWith(client.saveBlockTemplate({ name: 'None', blocks: [] }), 'invalid');
+    expect(await client.listBlockTemplates()).toEqual([saved]);
+    await client.deleteBlockTemplate(saved.id);
+    expect(await client.listBlockTemplates()).toEqual([]);
+    await failsWith(client.deleteBlockTemplate(saved.id), 'not_found');
+  });
+
+  it('keeps drafts in storage across reloads and ignores unreadable storage', async () => {
+    const data = new Map<string, string>();
+    const storage = {
+      getItem: (key: string) => data.get(key) ?? null,
+      setItem: (key: string, value: string) => void data.set(key, value),
+    };
+    const first = setup({ storage });
+    const { course } = await first.createCourse({ type: 'microlearning', title: 'Hold music' });
+    const again = setup({ storage });
+    expect((await again.getCourse(course.id)).course).toEqual(course);
+
+    data.set('carehub.learning.studio', '{not json');
+    expect(await setup({ storage }).listCourses()).toEqual([]);
+  });
+});
diff --git a/apps/web/src/features/learning/studio/data/memory-client.ts b/apps/web/src/features/learning/studio/data/memory-client.ts
new file mode 100644
index 0000000..32f623d
--- /dev/null
+++ b/apps/web/src/features/learning/studio/data/memory-client.ts
@@ -0,0 +1,212 @@
+import {
+  CourseSchema,
+  checkPublishable,
+  createCourse,
+  duplicateCourse,
+  newId as randomId,
+  parseCourse,
+  sampleCourses,
+} from '@carehub/learning';
+import type { Course, Id } from '@carehub/learning';
+import { StudioError } from './client';
+import type { BlockTemplate, StudioClient, StudioCourseSummary, StudioDraft } from './client';
+
+// A stand-in for the Studio course API (api.md) that keeps everything in the browser, used until the server
+// lands and in tests. It behaves like the server: a revision check on save, publish checks, versions and roll
+// back (a new version copying an old one), and copies that start unpublished.
+
+type Version = { version: number; publishedAt: string; note?: string; course: Course };
+type Entry = {
+  draft: Course;
+  revision: number;
+  updatedAt: string;
+  archived: boolean;
+  versions: Version[];
+};
+type Store = { courses: Record<Id, Entry>; templates: BlockTemplate[] };
+
+/** Options for {@link createMemoryStudioClient}. */
+export type MemoryStudioOptions = {
+  /** Keeps drafts across reloads (e.g. `window.localStorage`); without it they live in memory only. */
+  storage?: Pick<Storage, 'getItem' | 'setItem'>;
+  /** Defaults to "carehub.learning.studio". */
+  storageKey?: string;
+  /** Courses offered as examples to start from. Defaults to the package's sample courses. */
+  examples?: readonly Course[];
+  now?: () => Date;
+  newId?: () => Id;
+};
+
+const copy = <T>(value: T): T => structuredClone(value);
+const notFound = () => new StudioError('not_found', 'This was deleted, or the link is wrong.');
+
+function load(storage: MemoryStudioOptions['storage'], key: string): Store {
+  const store: Store = { courses: {}, templates: [] };
+  try {
+    const saved = JSON.parse(storage?.getItem(key) ?? 'null') as Partial<Store> | null;
+    for (const [id, entry] of Object.entries(saved?.courses ?? {})) {
+      const draft = parseCourse(entry.draft);
+      if (draft.ok) store.courses[id] = { ...entry, draft: draft.course };
+    }
+    if (Array.isArray(saved?.templates)) store.templates = saved.templates;
+  } catch {
+    // Unreadable storage: start empty.
+  }
+  return store;
+}
+
+/** A StudioClient keeping courses and block templates in memory, and in `storage` when given. */
+export function createMemoryStudioClient(options: MemoryStudioOptions = {}): StudioClient {
+  const { storage, storageKey = 'carehub.learning.studio', examples = sampleCourses } = options;
+  const now = () => (options.now?.() ?? new Date()).toISOString();
+  const newId = options.newId ?? randomId;
+  const store = load(storage, storageKey);
+  const persist = () => storage?.setItem(storageKey, JSON.stringify(store));
+
+  const entry = (courseId: Id): Entry => {
+    const found = store.courses[courseId];
+    if (!found) throw notFound();
+    return found;
+  };
+  const draftOf = (e: Entry): StudioDraft => ({
+    course: copy(e.draft),
+    revision: e.revision,
+    liveVersion: e.versions.at(-1)?.version ?? null,
+  });
+  const summary = (e: Entry): StudioCourseSummary => {
+    const live = e.versions.at(-1);
+    const same = live !== undefined && JSON.stringify(live.course) === JSON.stringify(e.draft);
+    return {
+      id: e.draft.id,
+      title: e.draft.title,
+      type: e.draft.type,
+      state: live === undefined ? 'draft' : same ? 'live' : 'changed',
+      version: live?.version ?? null,
+      updatedAt: e.updatedAt,
+      archived: e.archived,
+      listed: e.draft.settings.catalog.listed,
+    };
+  };
+  const add = (course: Course): Entry => {
+    const e: Entry = {
+      draft: course,
+      revision: 1,
+      updatedAt: now(),
+      archived: false,
+      versions: [],
+    };
+    store.courses[course.id] = e;
+    persist();
+    return e;
+  };
+  const publishCopy = (e: Entry, course: Course, note?: string): { version: number } => {
+    const version = (e.versions.at(-1)?.version ?? 0) + 1;
+    e.versions.push({
+      version,
+      publishedAt: now(),
+      ...(note ? { note } : {}),
+      course: copy(course),
+    });
+    persist();
+    return { version };
+  };
+  const setArchived = (courseId: Id, archived: boolean): StudioCourseSummary => {
+    const e = entry(courseId);
+    e.archived = archived;
+    persist();
+    return summary(e);
+  };
+
+  return {
+    async listCourses({ archived = false } = {}) {
+      return Object.values(store.courses)
+        .filter((e) => e.archived === archived)
+        .map(summary)
+        .sort((a, b) => b.updatedAt.localeCompare(a.updatedAt));
+    },
+    async createCourse({ type, title, exampleId }) {
+      if (exampleId === undefined)
+        return draftOf(add(createCourse({ type, title: title ?? '', id: newId() })));
+      const example = examples.find((c) => c.id === exampleId);
+      if (!example) throw new StudioError('not_found', 'This example is no longer available.');
+      const course = duplicateCourse(example, newId);
+      return draftOf(add({ ...course, title: title?.trim() || example.title }));
+    },
+    async getCourse(courseId) {
+      return draftOf(entry(courseId));
+    },
+    async saveCourse(courseId, course, revision) {
+      const e = entry(courseId);
+      if (revision !== e.revision)
+        throw new StudioError('conflict', 'Someone else saved this course since you opened it.');
+      if (course.id !== courseId || !CourseSchema.safeParse(course).success)
+        throw new StudioError('invalid', "This draft can't be saved as it is.");
+      Object.assign(e, { draft: copy(course), revision: e.revision + 1, updatedAt: now() });
+      persist();
+      return { revision: e.revision };
+    },
+    async publish(courseId, { note }) {
+      const e = entry(courseId);
+      const problems = checkPublishable(e.draft);
+      if (problems.length > 0)
+        throw new StudioError(
+          'cannot_publish',
+          "This can't be published yet. Fix the problems listed first.",
+          problems,
+        );
+      return publishCopy(e, e.draft, note?.trim());
+    },
+    async listVersions(courseId) {
+      return entry(courseId)
+        .versions.map(({ version, publishedAt, note, course }) => ({
+          version,
+          publishedAt,
+          title: course.title,
+          ...(note ? { note } : {}),
+        }))
+        .reverse();
+    },
+    async rollback(courseId, version) {
+      const e = entry(courseId);
+      const old = e.versions.find((v) => v.version === version);
+      if (!old) throw new StudioError('not_found', 'That version no longer exists.');
+      Object.assign(e, { draft: copy(old.course), revision: e.revision + 1, updatedAt: now() });
+      return publishCopy(e, old.course, `Rolled back to version ${version}`);
+    },
+    async duplicate(courseId) {
+      return summary(add(duplicateCourse(entry(courseId).draft, newId)));
+    },
+    async archive(courseId) {
+      return setArchived(courseId, true);
+    },
+    async unarchive(courseId) {
+      return setArchived(courseId, false);
+    },
+    async listExamples() {
+      return examples.map((c) => ({
+        id: c.id,
+        title: c.title,
+        type: c.type,
+        summary: c.summary ?? '',
+      }));
+    },
+    async listBlockTemplates() {
+      return copy(store.templates);
+    },
+    async saveBlockTemplate({ name, blocks }) {
+      const title = name.trim().slice(0, 80);
+      if (title === '' || blocks.length === 0)
+        throw new StudioError('invalid', 'Name the template and pick at least one block.');
+      const template: BlockTemplate = { id: newId(), name: title, blocks: copy(blocks) };
+      store.templates.push(template);
+      persist();
+      return copy(template);
+    },
+    async deleteBlockTemplate(templateId) {
+      const at = store.templates.findIndex((t) => t.id === templateId);
+      if (at < 0) throw new StudioError('not_found', 'This template was already deleted.');
+      store.templates.splice(at, 1);
+      persist();
+    },
+  };
+}
