+    fireEvent.click(screen.getByRole('button', { name: 'New course' }));
+    fireEvent.click(screen.getByRole('button', { name: 'Cancel' }));
+    expect(screen.queryByRole('dialog')).toBeNull();
+    expect(await client.listCourses()).toEqual([]);
